/* From Uiverse.io by talhaabu1 - Tags: checkbox */
.__UIV_SCOPE__ .checkbox-wrapper-23 *,
  .__UIV_SCOPE__ .checkbox-wrapper-23 *:after,
  .__UIV_SCOPE__ .checkbox-wrapper-23 *:before {
  box-sizing: border-box;
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input {
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input:checked + label svg path {
  stroke-dashoffset: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input:focus + label {
  transform: scale(1.03);
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input + label {
  display: block;
  border: 2px solid rgb(253, 237, 237);
  width: var(--size);
  height: var(--size);
  border-radius: 6px;
  cursor: pointer;
  transition: all .2s ease;
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input + label:active {
  transform: scale(1.05);
  border-radius: 12px;
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input + label svg {
  pointer-events: none;
  padding: 5%;
}

.__UIV_SCOPE__ .checkbox-wrapper-23 input + label svg path {
  fill: none;
  stroke: rgb(247, 247, 247);
  stroke-width: 4px;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 101;
  transition: all 250ms cubic-bezier(1,0,.37,.91);
}
